Show Solutions <p>Exercise 3 — Semaphore-based pool (faster alloc): <pre><code>#define POOL_N     20
#define BLOCK_SZ   128

static uint8_t pool_mem[POOL_N][BLOCK_SZ];
static bool    pool_used[POOL_N] = {false};
static SemaphoreHandle_t pool_sem;   // Counting, init to POOL_N
static SemaphoreHandle_t pool_lock;  // Mutex for pool_used array

void pool_init(void) {
    pool_sem  = xSemaphoreCreateCounting(POOL_N, POOL_N);
    pool_lock = xSemaphoreCreateMutex();
}

void* pool_alloc(TickType_t timeout) {
    if(xSemaphoreTake(pool_sem, timeout) != pdPASS)
        return NULL;  // Pool empty
    xSemaphoreTake(pool_lock, portMAX_DELAY);
    for(int i = 0; i &lt; POOL_N; i++) {
        if(!pool_used[i]) {
            pool_used[i] = true;
            xSemaphoreGive(pool_lock);
            return pool_mem[i];
        }
    }
    xSemaphoreGive(pool_lock);
    return NULL;  // Shouldn't happen
}

void pool_free(void *p) {
    int i = ((uint8_t*)p - pool_mem[0]) / BLOCK_SZ;
    xSemaphoreTake(pool_lock, portMAX_DELAY);
    pool_used[i] = false;
    xSemaphoreGive(pool_lock);
    xSemaphoreGive(pool_sem);   // Unblock any waiting alloc
}
</code></pre></p>

Function Behavior Jitter Source <code>vTaskDelay(N)</code> Sleep N ticks from now Execution time adds to period — jitter accumulates <code>vTaskDelayUntil(&amp;last, N)</code> Wake at absolute tick <code>last + N</code> Execution time consumed within period — near-zero jitter <pre><code>/* BAD: Accumulated drift — execution time shifts the next wake point */
void vPeriodicBad(void *p) {
    for (;;) {
        do_work();             /* Takes variable time */
        vTaskDelay(pdMS_TO_TICKS(10));   /* 10ms from NOW */
    }
}

/* GOOD: Fixed period — vTaskDelayUntil absorbs execution variation */
void vPeriodicGood(void *p) {
    TickType_t xLast = xTaskGetTickCount();
    for (;;) {
        do_work();             /* Variable time consumed inside period */
        vTaskDelayUntil(&amp;xLast, pdMS_TO_TICKS(10));  /* Wake at fixed absolute time */
    }
}
</code></pre>

