    }
}
</code></pre> <p>Exercise 2 — Solution sketch</p> <p>Create <code>TX_QUEUE sampleQ</code> (capacity 20, 1 word) and <code>TX_QUEUE batchQ</code> (capacity 5, 3 words for pointer + count). <code>SensorThread</code> calls <code>tx_queue_send</code> every 50 ms. <code>ProcessThread</code> batches 10 samples into a static array, then sends a pointer via <code>batchQ</code>. <code>TransmitThread</code> prints the batch and sets a <code>TX_EVENT_FLAGS_GROUP</code> flag. Measure queue depth with <code>tx_queue_info_get</code>.</p> <p>Exercise 3 — Solution sketch</p> <pre><code>#define BLOCK_SIZE 128
#define POOL_BLOCKS 20
static TX_BLOCK_POOL pktPool;
static TX_QUEUE      pktQueue;
static UCHAR         poolBuf[POOL_BLOCKS * (BLOCK_SIZE + sizeof(VOID*))];
static ULONG         queueStorage[POOL_BLOCKS];

VOID tx_application_define(VOID *mem) {
    tx_block_pool_create(&amp;pktPool, "PktPool", BLOCK_SIZE,
                         poolBuf, sizeof(poolBuf));
    tx_queue_create(&amp;pktQueue, "PktQ", 1,
                    queueStorage, sizeof(queueStorage));
}

static VOID producer_entry(ULONG arg) {
    VOID *blk;
    while (1) {
        if (tx_block_allocate(&amp;pktPool, &amp;blk, TX_NO_WAIT) == TX_SUCCESS) {
            /* fill blk */
            tx_queue_send(&amp;pktQueue, &amp;blk, TX_WAIT_FOREVER);
        }
        tx_thread_sleep(5);
    }
}

static VOID consumer_entry(ULONG arg) {
    VOID *blk;
    while (1) {
        tx_queue_receive(&amp;pktQueue, &amp;blk, TX_WAIT_FOREVER);
        /* process blk */
        tx_block_release(blk);
    }
}
</code></pre> <p>Exercise 4 — Guidance</p> <p>Add <code>tx_trace_enable(buf, sizeof(buf), 30)</code> before <code>tx_kernel_enter</code>. After the run, halt the debugger and dump <code>buf</code> to a binary file. Open in TraceX (free download from Microsoft). Use the Thread Execution Profile view for CPU percentages, the Semaphore Performance Statistics for wait times, and the Priority Inversion filter to detect inversion events.</p>

